'use client';

import { useState } from 'react';
import { useLanguage } from '@/lib/language-context';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { useToast } from '@/hooks/use-toast';

export function Hero() {
  const { t } = useLanguage();
  const [email, setEmail] = useState('');
  const { toast } = useToast();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (email) {
      toast({
        title: t('thanksMessage'),
        duration: 3000,
      });
      setTimeout(() => {
        window.location.href = '/signup';
      }, 1500);
    }
  };

  return (
    <section className="relative w-full overflow-hidden bg-[#f6f1e8] py-16 sm:py-24 lg:py-32">
      <div className="absolute inset-0 bg-paper-grid opacity-40" />
      <div className="absolute inset-0 bg-paper-noise opacity-50" />
      <div className="absolute -left-20 top-12 h-56 w-56 rounded-full bg-[#e58a4b]/15 blur-3xl" />
      <div className="absolute -right-16 bottom-10 h-72 w-72 rounded-full bg-[#1d6f5c]/15 blur-3xl" />

      <div className="container relative mx-auto px-4 sm:px-6 lg:px-8">
        <div className="mx-auto max-w-4xl text-center">
          <div className="mx-auto mb-6 h-px w-28 bg-gradient-to-r from-transparent via-[#1d6f5c] to-transparent" />
          <h1 className="mb-6 text-4xl font-semibold leading-tight text-[#14110c] sm:text-5xl lg:text-6xl xl:text-7xl">
            {t('heroTitle')}
          </h1>

          <p className="mb-12 text-lg text-[#3b352c] sm:text-xl lg:text-2xl">
            {t('heroSubtitle')}
          </p>

          <div className="mx-auto mb-4 w-fit rounded-full border border-[#1d6f5c]/40 bg-white/70 px-4 py-1 text-xs font-semibold uppercase tracking-[0.2em] text-[#1d6f5c] sm:text-sm">
            {t('heroCtaTitle')}
          </div>

          <div className="mx-auto max-w-2xl rounded-2xl border border-[#d9d1c2] bg-white/80 p-4 sm:p-6 shadow-ink-soft">
            <form onSubmit={handleSubmit}>
              <div className="flex flex-col gap-3 sm:flex-row sm:gap-2">
                <Input
                  type="email"
                  placeholder={t('emailPlaceholder')}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  className="h-12 flex-1 border-[#c8bfb0] bg-white text-base text-[#14110c] placeholder:text-[#8a7f71] focus:border-[#1d6f5c] focus:ring-[#1d6f5c] sm:h-14 sm:text-lg"
                  aria-label={t('emailPlaceholder')}
                />
                <Button
                  type="submit"
                  className="h-12 bg-[#1d6f5c] px-8 text-base font-semibold text-white hover:bg-[#165447] sm:h-14 sm:px-10 sm:text-lg"
                >
                  {t('heroCtaButton')}
                </Button>
              </div>

              <p className="mt-4 text-sm text-[#6a5f51] sm:text-base">
                {t('emailMicrocopy')}
              </p>
            </form>
          </div>
        </div>
      </div>
    </section>
  );
}
